export type IconName = keyof typeof icons;

export default function Icon({ name, size = 20 }: { name: IconName; size?: number }) {
  return (
    <svg className="icon" viewBox="0 0 24 24" width={size} height={size} aria-hidden="true">
      {icons[name]}
    </svg>
  );
}

const streamdownIcon =
  (name: IconName) =>
  ({ size, className, ...props }: SVGProps<SVGSVGElement> & { size?: number }) => (
    <svg className={`icon ${className ?? ""}`} viewBox="0 0 24 24" width={size} height={size} aria-hidden="true" {...props}>
      {icons[name]}
    </svg>
  );

// Streamdown's built-in controls use Solar icons too.
export const streamdownIcons = {
  CheckIcon: streamdownIcon("check"),
  CopyIcon: streamdownIcon("copy"),
  DownloadIcon: streamdownIcon("download"),
  ExternalLinkIcon: streamdownIcon("externalLink"),
  Loader2Icon: streamdownIcon("loader"),
  Maximize2Icon: streamdownIcon("maximize"),
  RotateCcwIcon: streamdownIcon("retry"),
  XIcon: streamdownIcon("close"),
  ZoomInIcon: streamdownIcon("zoomIn"),
  ZoomOutIcon: streamdownIcon("zoomOut"),
};

export function IconButton({
  name,
  title,
  onClick,
  size = 20,
  disabled = false,
  pressed,
  tooltip = false,
}: {
  name: IconName;
  title: string;
  onClick: () => void;
  size?: number;
  disabled?: boolean;
  pressed?: boolean;
  /** Labels the button with an animated tooltip instead of the native one; put siblings in a WarmTooltipGroup. */
  tooltip?: boolean;
}) {
  const button = (
    <button
      className={`icon-button ${pressed ? "active" : ""}`}
      title={tooltip ? undefined : title}
      aria-label={title}
      aria-pressed={pressed}
      onClick={onClick}
      disabled={disabled}
    >
      <Icon name={name} size={size} />
    </button>
  );
  return tooltip ? (
    <WarmTooltip content={title} surfaceColor="var(--sidebar)" inkColor="CanvasText" size="sm">
      {button}
    </WarmTooltip>
  ) : (
    button
  );
}
